def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    # Collect simple stats
    my_c = 0
    opp_c = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
    my_d = n - my_c
    opp_d = n - opp_c
    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Near the end, try to exploit known cooperators.
    # If opponent has cooperated very often, defect in last few rounds.
    if n >= 95:
        if opp_d <= 5:
            return 'D'
        # If opponent has defected a lot, keep defecting to avoid being suckered.
        if opp_d >= 70:
            return 'D'
        # Otherwise, if opponent's last action was D, punish briefly.
        if opp_last == 'D':
            return 'D'
        return 'C'

    # If opponent seems mostly cooperative, cooperate but occasionally probe.
    if opp_d <= max(2, n // 10):
        # Always cooperate in early rounds to build score.
        if n < 10:
            return 'C'
        # Defect only rarely, with deterministic-ish condition, to test.
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # If opponent is heavily defecting, retaliate to minimize losses.
    if opp_c <= max(1, n // 5):
        return 'D'

    # Tit-for-tat-ish with forgiveness: copy opponent's last move,
    # but forgive occasional defections to restore cooperation.
    if opp_last == 'D':
        # Count consecutive defections at the end.
        k = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                k += 1
            else:
                break
        # Punish one or two rounds, then forgive if they seem recoverable.
        if k == 1:
            return 'D'
        if k == 2:
            return 'C' if rng.random() < 0.5 else 'D'
        return 'D'
    else:
        # Opponent cooperated last. Cooperate back, but if we just defected
        # and they still cooperated, keep cooperating to exploit/groom them.
        return 'C'
